import { MetadataRoute } from 'next';
import { currentSiteBaseUrl, isPreviewSite } from '@/lib/siteRouting';

// Used in development mode; production uses public/robots.txt generated by scripts/generate-robots.js.
export const dynamic = 'force-static';

export default function robots(): MetadataRoute.Robots {
  if (isPreviewSite) {
    return { rules: [{ userAgent: '*', allow: '/' }] };
  }

  return {
    rules: [{ userAgent: '*', allow: '/' }],
    sitemap:
      currentSiteBaseUrl === 'https://fastgpt.cn'
        ? [`${currentSiteBaseUrl}/sitemap.xml`, `${currentSiteBaseUrl}/customers/sitemap.xml`]
        : `${currentSiteBaseUrl}/sitemap.xml`,
    host: currentSiteBaseUrl
  };
}
